Tested-by: Dietmar Eggemann <dietmar.eggemann@arm.com>
Link: https://lore.kernel.org/r/20240117190545.596057-1-vincent.guittot@linaro.org
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
The bug was caused by the failure to set `capacity_freq_ref` when `raw_capacity` is null, leading to skipped normalization steps. This resulted in improper handling of CPU capacity, particularly when the "capacity-dmips-mhz" setting was not configured, which could lead to incorrect CPU frequency references being used in scheduling decisions.

Here is the patch:

 static int
 init_cpu_capacity_callback(struct notifier_block *nb,
 			   unsigned long val,
 			   void *data)
 {
 	struct cpufreq_policy *policy = data;
 	int cpu;

-	if (!raw_capacity)
-		return 0;
-
 	if (val != CPUFREQ_CREATE_POLICY)
 		return 0;

 	pr_debug("cpu_capacity: init cpu capacity for CPUs [%*pbl] (to_visit=%*pbl)\n",
 		 cpumask_pr_args(policy->related_cpus),
 		 cpumask_pr_args(cpus_to_visit));

 	cpumask_andnot(cpus_to_visit, cpus_to_visit, policy->related_cpus);

 	for_each_cpu(cpu, policy->related_cpus) {
 		per_cpu(capacity_freq_ref, cpu) = policy->cpuinfo.max_freq;
 		freq_inv_set_max_ratio(cpu,
 				       per_cpu(capacity_freq_ref, cpu) * HZ_PER_KHZ);
 	}

 	if (cpumask_empty(cpus_to_visit)) {
-		topology_normalize_cpu_scale();
-		schedule_work(&update_topology_flags_work);
-		free_raw_capacity();
+		if (raw_capacity) {
+			topology_normalize_cpu_scale();
+			schedule_work(&update_topology_flags_work);
+			free_raw_capacity();
+		}
 		pr_debug("cpu_capacity: parsing done\n");
 		schedule_work(&parsing_done_work);
 	}

 	return 0;
 }


 static int __init register_cpufreq_notifier(void)
 {
 	int ret;

 	/*
 	 * On ACPI-based systems skip registering cpufreq notifier as cpufreq
 	 * information is not needed for cpu capacity initialization.
 	 */
-	if (!acpi_disabled || !raw_capacity)
+	if (!acpi_disabled)
 		return -EINVAL;

 	if (!alloc_cpumask_var(&cpus_to_visit, GFP_KERNEL))
 		return -ENOMEM;

 	cpumask_copy(cpus_to_visit, cpu_possible_mask);

 	ret = cpufreq_register_notifier(&init_cpu_capacity_notifier,
 					CPUFREQ_POLICY_NOTIFIER);

 	if (ret)
 		free_cpumask_var(cpus_to_visit);

 	return ret;
 }
 core_initcall(register_cpufreq_notifier);


